export type Booking = { id: number; lab: string; seats: number };

// Wrong: no ? modifier, so every field is required.
export type Patch<T> = { [K in keyof T]: T[K] };

export function apply(b: Booking, patch: Patch<Booking>): Booking {
  return { ...b, ...patch };
}

import { apply } from '../src/patch.ts';
declare const b: { id: number; lab: string; seats: number };
const r = apply(b, { seats: 30 }); // only one field
export { r };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { apply } from '../src/patch.ts';
const b = { id: 1, lab: 'BE-201', seats: 40 };
test('apply', () => assert.deepEqual(apply(b, { seats: 30 }), { id: 1, lab: 'BE-201', seats: 30 }));

