export type Lab = { readonly code: string; readonly capacity: number };

// Wrong: keeps readonly, so the copy cannot be reassigned.
export type Mutable<T> = { [K in keyof T]: T[K] };

export function thaw(lab: Lab): Mutable<Lab> {
  return { code: lab.code, capacity: lab.capacity };
}

import { thaw } from '../src/mutable.ts';
const d = thaw({ code: 'BE-201', capacity: 40 });
d.capacity = 50; // must be allowed — readonly removed
export { d };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { thaw } from '../src/mutable.ts';
test('thaw', () => { const d = thaw({ code: 'BE-201', capacity: 40 }); d.capacity = 50; assert.equal(d.capacity, 50); });

